CREATE INDEX IF NOT EXISTS idx_device_tokens_company_id ON public.device_tokens(company_id);

-- RLS
ALTER TABLE public.device_tokens ENABLE ROW LEVEL SECURITY;

-- Workers can manage their own tokens
